 async function submit(e:React.FormEvent){e.preventDefault();setBusy(true);setError('');try{if(mode==='register'){await api.post('/auth/register',{fullName,email,password});setMode('login');setIdentifier(email);setError('Account created. Use your email and password until your university ID is issued.');}else{const {data}=await api.post('/auth/login',{identifier,password});localStorage.setItem('ums_token',data.token);localStorage.setItem('ums_user',JSON.stringify(data.user));onLogin(data.user);}}catch(e){setError(messageOf(e));}finally{setBusy(false);}}
