function WorkflowWorkbench({kind,user}:{kind:'student'|'lecturer'|'hostel'|'engines';user:User}){
 const config:any={
  student:{title:'Student lifecycle',subtitle:'Applicant → Admitted Student → Registered Student → Graduated Student. Students submit requests; the Registrar approves official status changes.',endpoint:'/workflows/student',options:[['course-registration','Course registration'],['academic-records','Academic records / transcript request'],['progression-review','Progression review'],['retake-request','Request course retake'],['exam-eligibility-review','Exam eligibility review'],['deferment-request','Request deferment'],['attendance-appeal','Attendance appeal'],['graduation-clearance','Graduation clearance'],['alumni-record-request','Alumni records request']],fields:['session','semester','level','courseCodes','reason','requestType']},
  lecturer:{title:'Lecturer workflows',subtitle:'Two stages: course assignment and assessment/result submission. Official result publication remains a separately authorized decision.',endpoint:'/workflows/lecturer',options:[['course-assignment','Course assignment'],['assessment-results','Assessment / result submission']],fields:['courseCode','session','semester','studentReference','score','note']},
  hostel:{title:'Hostel operations',subtitle:'Room inventory, maintenance, temporary reservations, allocations, and checkout. Allocation requires verification of bed availability and payment.',endpoint:'/workflows/hostel',options:[['room','Room / bed inventory'],['maintenance','Maintenance request'],['reservation','Temporary reservation'],['allocation','Allocation request'],['checkout','Checkout']],fields:['hostel','room','bed','studentReference','session','reservationExpiresAt','details']},
  engines:{title:'System engines',subtitle:'Run explainable policy checks that produce findings for human review. Engines never make hiring, admission, progression, withdrawal, or graduation decisions.',endpoint:'/workflows/engines',options:[['recruitment','Recruitment review'],['progression','Progression review'],['graduation','Graduation clearance'],['eligibility','Eligibility review'],['capacity-reconciliation','Capacity reconciliation']],fields:['session','subjectReference','policyVersion','requestedChecks','inputs']}
 };
 const cfg=config[kind];const clearanceMode=kind==='student'&&['BURSARY','LECTURER','LECTURER_HOD'].includes(user.role);const clearanceOptions=[['clearance-academic','Submit academic clearance'],['clearance-finance','Submit finance clearance'],['clearance-library','Submit library clearance'],['clearance-department','Submit department clearance']];const studentOptions=kind!=='student'?cfg.options:clearanceMode?clearanceOptions:user.role==='ADMITTED_STUDENT'?[]:user.role==='REGISTERED_STUDENT'?cfg.options.filter((o:any)=>o[0]!=='alumni-record-request'):user.role==='GRADUATED_STUDENT'?cfg.options.filter((o:any)=>['academic-records','alumni-record-request'].includes(o[0])):cfg.options;const [stage,setStage]=useState((kind==='student'?studentOptions:cfg.options)[0]?.[0]||cfg.options[0][0]);const [title,setTitle]=useState('');const [values,setValues]=useState<Record<string,string>>({});const [busy,setBusy]=useState(false);const [error,setError]=useState('');const [notice,setNotice]=useState('');const [records,setRecords]=useState<any[]>([]);const [clearanceRecords,setClearanceRecords]=useState<any[]>([]);const [overview,setOverview]=useState<any>(null);const [decisionReasons,setDecisionReasons]=useState<Record<string,string>>({});const [decisionBusy,setDecisionBusy]=useState<string>('');const [matEnabled,setMatEnabled]=useState(false);const [matDepartmentCodes,setMatDepartmentCodes]=useState('{}');const [matSessions,setMatSessions]=useState('{}');const [matConfigBusy,setMatConfigBusy]=useState(false);const [matToggleBusy,setMatToggleBusy]=useState('');const [matriculationAccess,setMatriculationAccess]=useState<any>(null);const [generateMatricBusy,setGenerateMatricBusy]=useState(false);const [studentPolicyJson,setStudentPolicyJson]=useState(JSON.stringify({policyVersion:'student-academic-v1',registrationWindows:{},creditLimitsByLevel:{},gradingScale:[],progressionRules:{minimumCGPA:null,minimumCreditsPassed:null},graduationRequirementsByDepartment:{},attendanceMinimumPercent:null,examEligibilityRequiresPublishedAttendance:true,retakePolicy:'MANUAL_REVIEW'},null,2));const [studentPolicyBusy,setStudentPolicyBusy]=useState(false);const [clearanceStudentId,setClearanceStudentId]=useState('');const [clearanceSession,setClearanceSession]=useState('');const [clearanceDetails,setClearanceDetails]=useState('');const [clearanceBusy,setClearanceBusy]=useState(false);
 async function load(){try{if(kind==='student'&&['ADMITTED_STUDENT','REGISTERED_STUDENT','GRADUATED_STUDENT','STUDENT'].includes(user.role)){const o=await api.get('/workflows/student/me/overview');setOverview(o.data);if(['ADMITTED_STUDENT','REGISTERED_STUDENT'].includes(user.role)){const m=await api.get('/workflows/student/me/matriculation-access');setMatriculationAccess(m.data);}else setMatriculationAccess(null);}const module=kind==='student'?(clearanceMode?'graduation':'student-workflow'):kind==='lecturer'?'lecturer-workflow':kind==='hostel'?'hostel-workflow':'system-engine-evaluation';const r=await api.get(`/records/${module}`);setRecords(r.data.records||[]);if(kind==='student'&&user.role==='REGISTRAR'){const m=await api.get('/registrar/matriculation-config');const c=m.data.config||{};setMatEnabled(Boolean(c.enabled));setMatDepartmentCodes(JSON.stringify(c.departmentCodes||{},null,2));setMatSessions(JSON.stringify(c.sessions||{},null,2));const cl=await api.get('/records/graduation');setClearanceRecords((cl.data.records||[]).filter((x:any)=>x.data?.clearanceType));const sp=await api.get('/registrar/student-academic-policy');if(sp.data?.policy)setStudentPolicyJson(JSON.stringify(sp.data.policy,null,2));}}catch{/* Role-specific records remain scoped by the API; errors are shown through the workflow actions. */}}
 useEffect(()=>{void load()},[kind]);
 async function submit(e:React.FormEvent){e.preventDefault();setBusy(true);setError('');setNotice('');try{let payload:any={title:title.trim()};for(const [k,v] of Object.entries(values)){if(!v.trim())continue;if(k==='score')payload[k]=Number(v);else if(k==='reservationExpiresAt')payload[k]=new Date(v).toISOString();else if(k==='requestedChecks')payload[k]=v.split(',').map(x=>x.trim()).filter(Boolean);else if(k==='inputs'){try{payload[k]=JSON.parse(v)}catch{throw new Error('Inputs must be valid JSON.')}}else if(k==='courseCodes')payload[k]=v.split(',').map(x=>x.trim()).filter(Boolean);else payload[k]=v;}if(kind==='engines'){payload.policyVersion=payload.policyVersion||'not-configured';payload.inputs=payload.inputs||{};payload.requestedChecks=payload.requestedChecks||[];}let r;if(kind==='student'&&clearanceMode&&stage.startsWith('clearance-')){r=await api.post(`/workflows/clearances/${stage.replace('clearance-','')}`,{studentId:payload.studentId,session:payload.session,details:payload.details||payload.reason,evidenceReference:payload.evidenceReference});}else{r=await api.post(`${cfg.endpoint}/${stage}`,payload);}setNotice(r.data.message||'Workflow saved.');setTitle('');setValues({});await load()}catch(e){setError(messageOf(e))}finally{setBusy(false)}}
 async function saveMatriculationConfig(e:React.FormEvent){e.preventDefault();setMatConfigBusy(true);setError('');setNotice('');try{let departmentCodes:any,sessions:any;try{departmentCodes=JSON.parse(matDepartmentCodes);sessions=JSON.parse(matSessions)}catch{throw new Error('Department codes and session settings must be valid JSON objects.')}if(!departmentCodes||typeof departmentCodes!=='object'||Array.isArray(departmentCodes)||!sessions||typeof sessions!=='object'||Array.isArray(sessions))throw new Error('Department codes and session settings must be JSON objects.');const r=await api.put('/registrar/matriculation-config',{enabled:matEnabled,departmentCodes,sessions});setNotice(r.data.message||'Matriculation policy saved.')}catch(e){setError(messageOf(e))}finally{setMatConfigBusy(false)}}
 async function saveStudentAcademicPolicy(e:React.FormEvent){e.preventDefault();setStudentPolicyBusy(true);setError('');setNotice('');try{let policy:any;try{policy=JSON.parse(studentPolicyJson)}catch{throw new Error('Student academic policy must be valid JSON.')}const r=await api.put('/registrar/student-academic-policy',policy);setStudentPolicyJson(JSON.stringify(r.data.policy||policy,null,2));setNotice(r.data.message||'Student academic policy saved.')}catch(e){setError(messageOf(e))}finally{setStudentPolicyBusy(false)}}
 async function toggleMatriculationSession(sessionName:string,enabled:boolean){setMatToggleBusy(sessionName);setError('');setNotice('');try{const r=await api.post('/registrar/matriculation-config/session-toggle',{session:sessionName,enabled});const next=r.data.config?.sessions||{};setMatSessions(JSON.stringify(next,null,2));setMatEnabled(Boolean(r.data.config?.enabled));setNotice(r.data.message||'Session setting updated.');}catch(e){setError(messageOf(e))}finally{setMatToggleBusy('')}}
 async function generateMatriculationNumber(){setGenerateMatricBusy(true);setError('');setNotice('');try{const r=await api.post('/workflows/student/me/generate-matriculation',{});const savedUser=JSON.parse(localStorage.getItem('ums_user')||'{}');localStorage.setItem('ums_user',JSON.stringify({...savedUser,role:'REGISTERED_STUDENT',matricNumber:r.data.student?.matricNumber}));setNotice(r.data.message||'Matriculation number generated.');window.setTimeout(()=>window.location.reload(),700)}catch(e){setError(messageOf(e))}finally{setGenerateMatricBusy(false)}}
 async function submitRegistrarLibraryClearance(e:React.FormEvent){e.preventDefault();setClearanceBusy(true);setError('');setNotice('');try{const r=await api.post('/workflows/clearances/library',{studentId:clearanceStudentId.trim(),session:clearanceSession.trim(),details:clearanceDetails.trim()});setNotice(r.data.message||'Library clearance submitted.');setClearanceStudentId('');setClearanceSession('');setClearanceDetails('');await load()}catch(e){setError(messageOf(e))}finally{setClearanceBusy(false)}}
 async function decideStudent(recordId:string,outcome:'APPROVED'|'REJECTED'|'NEEDS_INFORMATION'){const reason=(decisionReasons[recordId]||'').trim();if(reason.length<5){setError('Enter a decision reason of at least 5 characters.');return;}setDecisionBusy(recordId);setError('');setNotice('');try{const r=await api.post(`/workflows/student/${recordId}/decision`,{outcome,reason});setNotice(r.data.message||'Decision recorded.');setDecisionReasons({...decisionReasons,[recordId]:''});await load()}catch(e){setError(messageOf(e))}finally{setDecisionBusy('')}}
 async function decideClearance(recordId:string,outcome:'APPROVED'|'REJECTED'|'NEEDS_INFORMATION'){const reason=(decisionReasons[recordId]||'').trim();if(reason.length<5){setError('Enter a decision reason of at least 5 characters.');return;}setDecisionBusy(recordId);setError('');setNotice('');try{const r=await api.post(`/workflows/clearances/${recordId}/decision`,{outcome,reason});setNotice(r.data.message||'Clearance decision recorded.');setDecisionReasons({...decisionReasons,[recordId]:''});await load()}catch(e){setError(messageOf(e))}finally{setDecisionBusy('')}}
 return <><PageHeading eyebrow="Connected role workflow" title={cfg.title} subtitle={cfg.subtitle}/>{kind==='student'&&overview&&<section className="bg-white rounded-2xl border border-slate-100 p-5 mb-6"><div className="flex flex-wrap items-start justify-between gap-4"><div><p className="text-xs uppercase tracking-wide text-slate-400">Your official student stage</p><h2 className="text-xl font-bold mt-1">{String(overview.account?.role||user.role).replaceAll('_',' ')}</h2><p className="text-sm text-slate-500 mt-1">{overview.account?.fullName} · {overview.account?.department||'Department not assigned'}</p></div><div><p className="text-xs text-slate-400">Matriculation number</p><p className="font-bold mt-1">{overview.account?.matricNumber||'Not yet issued'}</p></div></div>{kind==='student'&&user.role==='ADMITTED_STUDENT'&&matriculationAccess?.eligible&&<div className="mt-5 rounded-xl border border-emerald-200 bg-emerald-50 p-4"><p className="font-semibold text-emerald-950">Matriculation generation is open for your admitted session ({matriculationAccess.session}).</p><p className="text-sm text-emerald-800 mt-1">Generate your number once. After generation, your account moves to Registered Student and this button disappears.</p><button type="button" disabled={generateMatricBusy} onClick={()=>void generateMatriculationNumber()} className="mt-3 rounded-xl bg-forest px-5 py-3 text-sm font-semibold text-white disabled:opacity-50">{generateMatricBusy?'Generating…':'Generate matriculation number'}</button></div>}{overview.applications?.length>0&&<p className="text-sm text-slate-600 mt-3">Admission applications: {overview.applications.map((a:any)=>`${a.applicationNumber||'Application'} — ${a.status}`).join(' · ')}</p>}<div className="grid sm:grid-cols-3 gap-3 mt-4"><div className="rounded-xl bg-slate-50 p-3"><p className="text-xs text-slate-500">CGPA</p><p className="text-lg font-bold">{overview.academicSummary?.cgpa??'Not available'}</p><p className="text-xs text-slate-400">Published results only</p></div><div className="rounded-xl bg-slate-50 p-3"><p className="text-xs text-slate-500">Attendance</p><p className="text-lg font-bold">{overview.attendanceSummary?.percentage==null?'Not available':`${overview.attendanceSummary.percentage}%`}</p><p className="text-xs text-slate-400">Does not decide exam eligibility</p></div><div className="rounded-xl bg-slate-50 p-3"><p className="text-xs text-slate-500">Graduation progress</p><p className="text-lg font-bold">{overview.graduationProgress?.length?overview.graduationProgress.map((g:any)=>`${g.approvedClearances.length}/4`).join(', '):'Not started'}</p><p className="text-xs text-slate-400">Approved clearances by session</p></div></div></section>}<div className="rounded-2xl border border-emerald-100 bg-emerald-50 p-4 text-sm text-emerald-950 mb-6">{cfg.subtitle}{kind==='student'&&<p className="mt-2">Matriculation numbers follow <strong>YY/DEPARTMENTCODE/NNNN</strong>. Only newly admitted students can generate one, and only after the Registrar enables their admission session. Course registration requires an issued matriculation number. Graduation is finalized only after independently approved clearance records.</p>}</div>{error&&<p className="mb-4 rounded-xl bg-red-50 text-red-700 p-3 text-sm">{error}</p>}{notice&&<p className="mb-4 rounded-xl bg-green-50 text-green-800 p-3 text-sm">{notice}</p>}{!(kind==='student'&&(user.role==='REGISTRAR'||user.role==='ADMITTED_STUDENT'))&&<form onSubmit={submit} className="bg-white rounded-2xl border border-slate-100 p-6 mb-7"><label className="block text-sm font-semibold">Workflow stage<select className="field mt-2" value={stage} onChange={e=>setStage(e.target.value)}>{(kind==='student'?studentOptions:cfg.options).map((o:any)=><option value={o[0]} key={o[0]}>{o[1]}</option>)}</select></label><label className="block text-sm font-semibold mt-4">Title / reference<input className="field mt-2" required minLength={2} maxLength={180} value={title} onChange={e=>setTitle(e.target.value)} placeholder="Describe this request or review"/></label><div className="grid md:grid-cols-2 gap-4 mt-4">{(kind==='student'&&clearanceMode?(['studentId','session','details']):kind==='student'?(({ 'course-registration':['session','semester','level','courseCodes'],'academic-records':['session','requestType','reason'],'progression-review':['session','semester','level','reason'],'retake-request':['session','semester','courseCodes','reason'],'exam-eligibility-review':['session','semester','courseCodes','reason'],'deferment-request':['session','semester','reason'],'attendance-appeal':['session','semester','reason'],'graduation-clearance':['session','reason'],'alumni-record-request':['requestType','reason']} as Record<string,string[]>)[stage]||cfg.fields):cfg.fields).map((field:string)=><label key={field} className="text-sm font-medium">{({session:'Academic session',semester:'Semester',level:'Current level',courseCodes:'Course codes (comma-separated)',reason:'Reason / supporting context',requestType:'Request type',studentId:'Student account ID',details:'Clearance details / evidence summary',courseCode:'Course code',studentReference:'Student reference',score:'Score (0–100)',note:'Academic note',hostel:'Hostel',room:'Room',bed:'Bed identifier',reservationExpiresAt:'Reservation expiry (ISO date/time)',subjectReference:'Subject reference',policyVersion:'Policy version',requestedChecks:'Requested checks (comma-separated)',inputs:'Input evidence as JSON'} as any)[field]||field}<input type={field==='score'?'number':field==='reservationExpiresAt'?'datetime-local':'text'} min={field==='score'?0:undefined} max={field==='score'?100:undefined} className="field mt-2" value={values[field]||''} onChange={e=>setValues({...values,[field]:e.target.value})} placeholder={field==='inputs'?'{}':field==='requestedChecks'?'e.g. minimum credits, required clearance':field}/></label>)}</div><button disabled={busy} className="mt-5 rounded-xl bg-forest text-white px-5 py-3 text-sm font-semibold disabled:opacity-50">{busy?'Saving…':'Submit workflow'}</button></form>}{kind==='student'&&user.role==='REGISTRAR'&&<form onSubmit={saveStudentAcademicPolicy} className="bg-white rounded-2xl border border-slate-100 p-6 mb-7"><h2 className="font-bold text-lg">Student academic policy</h2><p className="text-sm text-slate-500 mt-1">Configure Crestfield's approved academic rules explicitly. No grading scale, credit limit, progression threshold, attendance threshold, or graduation requirement is invented. Session keys and level keys must match student/course records.</p><label className="block text-sm font-medium mt-4">Policy configuration (JSON)<textarea required className="field mt-2 font-mono text-xs" rows={18} value={studentPolicyJson} onChange={e=>setStudentPolicyJson(e.target.value)}/></label><p className="text-xs text-slate-500 mt-2">Include registrationWindows, creditLimitsByLevel, gradingScale, progressionRules, graduationRequirementsByDepartment, attendanceMinimumPercent, examEligibilityRequiresPublishedAttendance, and retakePolicy. Empty policy sections intentionally block decisions that depend on missing rules.</p><button disabled={studentPolicyBusy} className="mt-4 rounded-xl bg-forest text-white px-4 py-3 text-sm font-semibold disabled:opacity-50">{studentPolicyBusy?'Saving…':'Save student academic policy'}</button></form>}{kind==='student'&&user.role==='REGISTRAR'&&<form onSubmit={saveMatriculationConfig} className="bg-white rounded-2xl border border-slate-100 p-6 mb-7"><h2 className="font-bold text-lg">Matriculation policy</h2><p className="text-sm text-slate-500 mt-1">Configure the department code and explicitly enable each academic session. Keys in the department-code object must match the accepted offer programme/department label exactly. When an offer is accepted, the accepted programme and faculty are saved to the student account for matriculation checks.</p><label className="flex items-center gap-3 mt-4 text-sm font-medium"><input type="checkbox" checked={matEnabled} onChange={e=>setMatEnabled(e.target.checked)}/> Enable matriculation generation globally</label><div className="grid md:grid-cols-2 gap-4 mt-4"><label className="text-sm font-medium">Department codes (JSON)<textarea className="field mt-2 font-mono text-xs" rows={6} value={matDepartmentCodes} onChange={e=>setMatDepartmentCodes(e.target.value)} placeholder={'{\n  \"Computer Science\": \"CSC\"\n}'}/></label><label className="text-sm font-medium">Academic session switches (JSON)<textarea className="field mt-2 font-mono text-xs" rows={6} value={matSessions} onChange={e=>setMatSessions(e.target.value)} placeholder={'{\n  \"2026/2027\": { \"enabled\": true }\n}'}/></label></div><div className="mt-5 rounded-xl border border-slate-200 p-4"><h3 className="font-semibold">Per-session generation access</h3><p className="text-sm text-slate-500 mt-1">Use the button for the admitted cohort. This immediately opens or closes generation for newly admitted students whose admission session matches. Registered and graduated students never see the generation button.</p><div className="mt-3 space-y-2">{(()=>{try{const parsed=JSON.parse(matSessions||'{}');return Object.entries(parsed).map(([sessionName,value]:[string,any])=><div key={sessionName} className="flex flex-col sm:flex-row sm:items-center justify-between gap-3 rounded-lg bg-slate-50 p-3"><div><p className="font-medium">{sessionName}</p><p className="text-xs text-slate-500">{value?.enabled?'Generation currently enabled':'Generation currently disabled'}</p></div><button type="button" disabled={matToggleBusy===sessionName} onClick={()=>void toggleMatriculationSession(sessionName,!value?.enabled)} className={`rounded-lg px-4 py-2 text-sm font-semibold text-white disabled:opacity-50 ${value?.enabled?'bg-rose-700':'bg-forest'}`}>{matToggleBusy===sessionName?'Updating…':value?.enabled?'Disable generation':'Allow admitted students to generate'}</button></div>); }catch{return <p className="text-sm text-rose-700">Save valid session JSON before using session controls.</p>}})()}</div></div><button disabled={matConfigBusy} className="mt-4 rounded-xl bg-forest text-white px-4 py-3 text-sm font-semibold disabled:opacity-50">{matConfigBusy?'Saving…':'Save department codes and session setup'}</button></form>} {kind==='student'&&user.role==='REGISTRAR'&&<form onSubmit={submitRegistrarLibraryClearance} className="bg-white rounded-2xl border border-slate-100 p-6 mb-7"><h2 className="font-bold text-lg">Submit library clearance</h2><p className="text-sm text-slate-500 mt-1">Record the library unit's clearance evidence for a matriculated student. Final approval remains a separate audited action.</p><div className="grid md:grid-cols-2 gap-4 mt-4"><label className="text-sm font-medium">Student account ID<input required className="field mt-2" value={clearanceStudentId} onChange={e=>setClearanceStudentId(e.target.value)}/></label><label className="text-sm font-medium">Graduation session<input required className="field mt-2" value={clearanceSession} onChange={e=>setClearanceSession(e.target.value)} placeholder="2026/2027"/></label><label className="text-sm font-medium md:col-span-2">Clearance evidence<textarea required minLength={5} className="field mt-2" rows={3} value={clearanceDetails} onChange={e=>setClearanceDetails(e.target.value)}/></label></div><button disabled={clearanceBusy} className="mt-4 rounded-xl bg-forest text-white px-4 py-3 text-sm font-semibold">{clearanceBusy?'Submitting…':'Submit library clearance'}</button></form>}<section className="bg-white border border-slate-100 rounded-2xl p-5"><h2 className="font-bold">Recent records</h2><p className="text-sm text-slate-500 mt-1">{kind==='student'&&user.role==='REGISTRAR'?'Review student requests here. Decisions require a reason and are audited.':'Your visible workflow requests and their current review status.'}</p><div className="mt-4 space-y-3">{records.map(r=><article key={r._id} className="border rounded-xl p-4"><div className="flex flex-wrap justify-between gap-2"><strong>{r.title}</strong><Status value={r.status}/></div><p className="text-xs text-slate-400 mt-2">{r.reference||r._id} · {new Date(r.createdAt).toLocaleString()}</p>{kind==='student'&&r.data?.stage&&<p className="mt-2 text-sm text-slate-600">Stage: {String(r.data.stage).replaceAll('-',' ')}{r.data.session?` · ${r.data.session}`:''}{r.data.semester?` · ${r.data.semester}`:''}</p>}{kind==='student'&&user.role==='REGISTRAR'&&['SUBMITTED','UNDER_REVIEW','NEEDS_INFORMATION'].includes(r.status)&&<div className="mt-4 border-t pt-4"><label className="block text-sm font-medium">Decision reason<textarea className="field mt-2" rows={2} value={decisionReasons[r._id]||''} onChange={e=>setDecisionReasons({...decisionReasons,[r._id]:e.target.value})} placeholder="Explain the decision and any policy basis"/></label><div className="flex flex-wrap gap-2 mt-3">{(['APPROVED','REJECTED','NEEDS_INFORMATION'] as const).map(outcome=><button type="button" key={outcome} disabled={decisionBusy===r._id} onClick={()=>void decideStudent(r._id,outcome)} className="rounded-lg border px-3 py-2 text-xs font-semibold disabled:opacity-50">{decisionBusy===r._id?'Saving…':outcome.replaceAll('_',' ')}</button>)}</div></div>}</article>)}{!records.length&&<p className="text-sm text-slate-400 py-5">No visible records yet. Submit a workflow to create a record.</p>}</div></section>{kind==='student'&&user.role==='REGISTRAR'&&<section className="bg-white border border-slate-100 rounded-2xl p-5 mt-6"><h2 className="font-bold">Independent graduation clearances</h2><p className="text-sm text-slate-500 mt-1">Only clearances approved here count toward the Registrar's final graduation decision.</p><div className="mt-4 space-y-3">{clearanceRecords.map(r=><article key={r._id} className="border rounded-xl p-4"><div className="flex flex-wrap justify-between gap-2"><strong>{r.title}</strong><Status value={r.status}/></div><p className="text-xs text-slate-500 mt-2">{r.data?.clearanceType} · {r.data?.matricNumber} · {r.data?.session}</p><p className="text-sm text-slate-600 mt-2">{r.data?.details}</p>{['SUBMITTED','UNDER_REVIEW','NEEDS_INFORMATION'].includes(r.status)&&<div className="mt-3"><label className="block text-sm">Decision reason<textarea className="field mt-1" rows={2} value={decisionReasons[r._id]||''} onChange={e=>setDecisionReasons({...decisionReasons,[r._id]:e.target.value})}/></label><div className="flex gap-2 mt-2">{(['APPROVED','REJECTED','NEEDS_INFORMATION'] as const).map(o=><button type="button" key={o} disabled={decisionBusy===r._id} onClick={()=>void decideClearance(r._id,o)} className="rounded-lg border px-3 py-2 text-xs font-semibold">{o.replaceAll('_',' ')}</button>)}</div></div>}</article>)}{!clearanceRecords.length&&<p className="text-sm text-slate-400 py-4">No independent clearance submissions yet.</p>}</div></section>}</>;
}

function ModulePage({moduleKey,user}:{moduleKey:string;user:User}){
 const cfg=modules[moduleKey];const [items,setItems]=useState<any[]>([]);const [error,setError]=useState('');const [show,setShow]=useState(false);const [busy,setBusy]=useState(false);
 const [title,setTitle]=useState('');const [status,setStatus]=useState(cfg.statuses[0]);const [data,setData]=useState<Record<string,string>>({});
 async function load(){try{const r=await api.get(`/records/${moduleKey}`);setItems(r.data.records)}catch(e){setError(messageOf(e))}}
 useEffect(()=>{load()},[moduleKey]);
 async function create(e:React.FormEvent){e.preventDefault();setBusy(true);setError('');try{await api.post(`/records/${moduleKey}`,{title,status,data});setShow(false);setTitle('');setData({});await load()}catch(e){setError(messageOf(e))}finally{setBusy(false)}}
 return <><PageHeading eyebrow="University operations" title={cfg.title} subtitle={cfg.subtitle} action={moduleKey!=='graduation'?<button onClick={()=>setShow(!show)} className="bg-forest text-white px-4 py-3 rounded-xl text-sm font-semibold">+ Add record</button>:undefined}/><div className="bg-emerald-50 border border-emerald-100 text-emerald-900 rounded-2xl p-4 text-sm leading-6 mb-6">{cfg.description}</div>{error&&<div className="mb-4 bg-red-50 text-red-700 rounded-xl p-3 text-sm">{error}</div>}{show&&<form onSubmit={create} className="bg-white p-6 rounded-2xl border border-slate-100 mb-6"><h2 className="font-bold mb-4">Add {cfg.title.toLowerCase()} record</h2><label className="block text-sm font-medium">Record title<input required value={title} onChange={e=>setTitle(e.target.value)} className="field mt-2" placeholder={cfg.fields[0]}/></label><label className="block text-sm font-medium mt-4">Status<select value={status} onChange={e=>setStatus(e.target.value)} className="field mt-2">{cfg.statuses.map(s=><option key={s}>{s}</option>)}</select></label><div className="grid md:grid-cols-2 gap-4 mt-4">{cfg.fields.map((f,i)=><label key={f} className="text-sm font-medium">{f}<input value={data[f]||''} onChange={e=>setData({...data,[f]:e.target.value})} className="field mt-2" placeholder={f}/></label>)}</div><div className="flex gap-3 mt-5"><button disabled={busy} className="bg-forest text-white rounded-xl px-5 py-2.5 text-sm font-semibold">{busy?'Saving…':'Save record'}</button><button type="button" onClick={()=>setShow(false)} className="px-5 py-2.5 rounded-xl bg-slate-100 text-sm">Cancel</button></div></form>}<div className="grid md:grid-cols-2 xl:grid-cols-3 gap-4">{items.map(r=><article key={r._id} className="bg-white rounded-2xl p-5 border border-slate-100 shadow-soft"><div className="flex justify-between gap-3"><span className="text-xs text-slate-400">{moduleKey.toUpperCase()} RECORD</span><Status value={r.status}/></div><h3 className="font-bold mt-3 break-words">{r.title}</h3><p className="text-xs text-slate-400 mt-2">{r.reference||`Created ${new Date(r.createdAt).toLocaleDateString()}`}</p><div className="mt-4 space-y-2">{Object.entries(r.data||{}).filter(([,v])=>String(v).trim()).slice(0,4).map(([k,v])=><p key={k} className="text-sm text-slate-600"><span className="text-slate-400">{k}: </span>{String(v)}</p>)}</div></article>)}</div>{items.length===0&&<div className="bg-white rounded-2xl border border-slate-100"><Empty title={`No ${cfg.title.toLowerCase()} records`} text="Use Add record to create the first entry. Records are saved to your MongoDB database."/></div>}</>
}
function Audit({user}:{user:User}){
 const [logs,setLogs]=useState<any[]>([]);const [error,setError]=useState('');const [query,setQuery]=useState('');const [action,setAction]=useState('');const [from,setFrom]=useState('');const [to,setTo]=useState('');const [page,setPage]=useState(1);const [pages,setPages]=useState(1);const [total,setTotal]=useState(0);const [actions,setActions]=useState<string[]>([]);const [busy,setBusy]=useState(false);
 async function load(nextPage=page){setBusy(true);setError('');try{const {data}=await api.get('/audit',{params:{q:query||undefined,action:action||undefined,from:from||undefined,to:to||undefined,page:nextPage,limit:25}});setLogs(data.logs||[]);setPages(data.pages||1);setTotal(data.total||0);setActions(data.actions||[]);setPage(nextPage);}catch(e){setError(messageOf(e));}finally{setBusy(false)}}
 useEffect(()=>{void load(1)},[query,action,from,to]);
 return <><PageHeading eyebrow="Security & accountability" title="Audit trail" subtitle="Search read-only administrative and security events. Passwords, tokens and other secrets are never displayed." action={<button onClick={()=>void load()} className="rounded-xl border bg-white px-4 py-3 text-sm font-semibold">{busy?'Refreshing…':'Refresh'}</button>}/>
 <section className="bg-white rounded-2xl border border-slate-100 p-4 mb-5"><div className="grid sm:grid-cols-2 xl:grid-cols-4 gap-3"><label className="text-xs font-semibold text-slate-500">Search events<input className="field mt-1" value={query} onChange={e=>setQuery(e.target.value)} placeholder="Actor, action, resource, ID"/></label><label className="text-xs font-semibold text-slate-500">Action<select className="field mt-1" value={action} onChange={e=>setAction(e.target.value)}><option value="">All actions</option>{actions.map(a=><option key={a}>{a}</option>)}</select></label><label className="text-xs font-semibold text-slate-500">From date<input type="date" className="field mt-1" value={from} onChange={e=>setFrom(e.target.value)}/></label><label className="text-xs font-semibold text-slate-500">To date<input type="date" className="field mt-1" value={to} onChange={e=>setTo(e.target.value)}/></label></div><div className="flex justify-between items-center mt-4"><p className="text-xs text-slate-500">{total} matching events · Page {page} of {pages}</p><button onClick={()=>{setQuery('');setAction('');setFrom('');setTo('');setPage(1)}} className="text-sm text-leaf font-semibold">Clear filters</button></div></section>
 {error&&<p className="mb-4 rounded-xl bg-red-50 text-red-700 p-4 text-sm">{error}</p>}<div className="bg-white rounded-2xl border border-slate-100 overflow-hidden">{logs.length===0?<Empty title={busy?'Loading audit events…':'No matching audit events'} text="Try changing the filters or check back after activity occurs."/>:<div className="overflow-x-auto"><table className="w-full text-sm"><thead className="bg-slate-50"><tr>{['Time','Actor','Action','Resource','IP'].map(h=><th key={h} className="p-4 text-left font-medium text-slate-500">{h}</th>)}</tr></thead><tbody>{logs.map(l=><tr key={l._id} className="border-t border-slate-100"><td className="p-4 whitespace-nowrap">{new Date(l.createdAt).toLocaleString()}</td><td className="p-4">{l.actorEmail||'System'}</td><td className="p-4 font-medium">{l.action}</td><td className="p-4">{l.resource||'—'} {l.resourceId||''}</td><td className="p-4">{l.ipAddress||'—'}</td></tr>)}</tbody></table></div>}<div className="flex items-center justify-between border-t p-4"><button disabled={page<=1||busy} onClick={()=>void load(page-1)} className="rounded-lg border px-3 py-2 text-sm disabled:opacity-40">Previous</button><span className="text-xs text-slate-500">Page {page} / {pages}</span><button disabled={page>=pages||busy} onClick={()=>void load(page+1)} className="rounded-lg border px-3 py-2 text-sm disabled:opacity-40">Next</button></div></div></>;
}

export default App;
